#include "core/word_characters.hpp"

#include <algorithm>
#include <array>
#include <iterator>

namespace bucu::core {

namespace {

struct CodePointRange {
    char32_t first;
    char32_t last;
};

// Generated by scripts/update-deps.sh from the Unicode Character Database: the code points of
// general categories L and N, as merged ranges in ascending order.
constexpr auto kWordRanges = std::to_array<CodePointRange>({
#include "word_characters.inc"
});

constexpr char32_t kUnderscore = U'_';

}  // namespace

bool is_word_character(char32_t code_point) {
    if (code_point == kUnderscore) {
        return true;
    }
    const auto* const it =
        std::ranges::upper_bound(kWordRanges, code_point, {}, &CodePointRange::first);
    return it != std::begin(kWordRanges) && code_point <= std::prev(it)->last;
}

}  // namespace bucu::core
